class MemoryIStream : public I {
 public:
  MemoryIStream(const char* data, int64_t size) : I("<MemoryStream>"), _data(data), size(size), pos(0) {}

  bool read(char c[], int n) override {
    if (_pos + n > size) {
      throw std::runtime_error("read past end");
    }
    std::memcpy(c, _data + _pos, static_cast<size_t>(n));
    _pos += n;
    return _pos < size;
  }

  uint64_t tellg() override { return static_cast<uint64_t>(_pos); }
  void seekg(uint64_t pos) override { _pos = static_cast<int64_t>(pos); }

 private:
  const char* _data;
  int64_t _size;
  int64_t _pos;
};

